var main = tree.current_scene
var H = load("res://tests/helpers/sm11e_m3a_scen.gd")
return H.setup(1, {"cp": {"2": 0}})

var C = load("res://scripts/codex/space_wolves/SWCommon.gd")
var nobz := ""
for eid in C.engaged_enemy_ids("U_OUTRIDER_SQUAD_A"):
	if "NOBZ" in str(GameState.state.units[eid].get("meta", {}).get("keywords", [])):
		nobz = str(eid)
if nobz == "":
	return "no engaged Nobz"
GameState.state.units[nobz]["meta"]["enhancements"] = ["Wimp-kickaz"]
GameState.state["factions"]["2"].merge({"detachment": "Bully Boyz", "detachments": ["Bully Boyz"]}, true)
return str(MoveTypes.get_type("fall_back").select_mode("U_OUTRIDER_SQUAD_A", GameState.state).get("mode", ""))

